      {enabled && (slots.selected = <p>Selected {(function* renderSteps() { yield <b>First step {count}</b>; return <Forms n={count} one="step" other="steps" />; })()}</p>)}
      Final visible children {count}
    </Card><footer>After assignment {account.name}</footer></main><p>After local shadow {count}</p></>;
    }

